/*
 * AuthContext — the app-wide session source of truth.
 *
 * Wraps the API seam (getApi()) so screens read the current session/user/org and
 * call sign-in / sign-out without knowing whether the backend is real or mocked.
 * On mount it hydrates from `me()`. Sign-in flows support the TOTP two-step:
 * `login` may return `totp-required`, which screens resolve via `verifyTotp`.
 *
 * FROZEN: screen agents consume `useAuth()`; they do not edit this file.
 */
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react'
import { getApi } from '../api'
import type { LoginInput, LoginResult, Session, SignUpInput, User } from '../api/types'

interface AuthContextValue {
  /** True until the initial `me()` hydration resolves. */
  loading: boolean
  session: Session | null
  user: User | null
  isAuthenticated: boolean

  signup: (input: SignUpInput) => Promise<Session>
  login: (input: LoginInput) => Promise<LoginResult>
  verifyTotp: (challengeId: string, code: string) => Promise<Session>
  /** Resolve a pending login challenge with a single-use recovery code. */
  loginWithRecovery: (challengeId: string, recoveryCode: string) => Promise<Session>
  /** WebAuthn sign-in (passwordless via `{email}`, or 2FA via `{challengeId}`). */
  loginWithPasskey: (req: { email?: string; challengeId?: string }) => Promise<Session>
  /** Begin org SSO. Real backend navigates away (OIDC); mock returns a session. */
  beginSSO: (returnTo?: string) => Promise<Session | void>
  /** Finish an SSO round-trip on the /auth/callback landing route. */
  completeSSO: () => Promise<Session | null>
  logout: () => Promise<void>
  /** Re-read the current user (after account/totp/passkey changes). */
  refresh: () => Promise<void>
}

const AuthContext = createContext<AuthContextValue | null>(null)

export function AuthProvider({ children }: { children: ReactNode }) {
  const api = getApi()
  const [session, setSession] = useState<Session | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let alive = true
    api
      .me()
      .then((s) => alive && setSession(s))
      .catch(() => { if (alive) setSession(null) })
      .finally(() => alive && setLoading(false))
    return () => {
      alive = false
    }
  }, [api])

  const signup = useCallback(
    async (input: SignUpInput) => {
      const s = await api.signup(input)
      setSession(s)
      return s
    },
    [api],
  )

  const login = useCallback(
    async (input: LoginInput): Promise<LoginResult> => {
      const result = await api.login(input)
      if (result.kind === 'session') setSession(result.session)
      return result
    },
    [api],
  )

  const verifyTotp = useCallback(
    async (challengeId: string, code: string) => {
      const s = await api.verifyTotp(challengeId, code)
      setSession(s)
      return s
    },
    [api],
  )

  const loginWithRecovery = useCallback(
    async (challengeId: string, recoveryCode: string) => {
      const s = await api.loginWithRecovery(challengeId, recoveryCode)
      setSession(s)
      return s
    },
    [api],
  )

  const loginWithPasskey = useCallback(
    async (req: { email?: string; challengeId?: string }) => {
      const s = await api.loginWithPasskey(req)
      setSession(s)
      return s
    },
    [api],
  )

  const beginSSO = useCallback(
    async (returnTo?: string) => {
      // Real backend navigates the browser away (no return); mock resolves a session.
      const s = await api.beginSSO(returnTo)
      if (s) setSession(s)
      return s
    },
    [api],
  )

  const completeSSO = useCallback(async () => {
    const s = await api.completeSSO()
    setSession(s)
    return s
  }, [api])

  const logout = useCallback(async () => {
    // Best-effort: always clear the local session so Sign Out works even if the
    // server call fails (e.g. an expired session or a transient error).
    try {
      await api.logout()
    } finally {
      setSession(null)
    }
  }, [api])

  const refresh = useCallback(async () => {
    const s = await api.me()
    setSession(s)
  }, [api])

  // Re-read live roles when returning to the console and while it stays open.
  // The API is authoritative on every operation; this keeps navigation in sync.
  const userId = session?.user.id
  const orgId = session?.org.id
  useEffect(() => {
    if (!userId || !orgId) return
    let active = true
    let pending = false
    const revalidate = async () => {
      if (pending || document.visibilityState === 'hidden') return
      pending = true
      try {
        const current = await api.me()
        if (active) setSession(current)
      } catch { /* Keep the session during transient outages; server checks still apply. */ }
      finally { pending = false }
    }
    const onFocus = () => { void revalidate() }
    window.addEventListener('focus', onFocus)
    document.addEventListener('visibilitychange', onFocus)
    const timer = window.setInterval(onFocus, 60_000)
    return () => {
      active = false
      window.clearInterval(timer)
      window.removeEventListener('focus', onFocus)
      document.removeEventListener('visibilitychange', onFocus)
    }
  }, [api, userId, orgId])

  const value = useMemo<AuthContextValue>(
    () => ({
      loading,
      session,
      user: session?.user ?? null,
      isAuthenticated: session != null,
      signup,
      login,
      verifyTotp,
      loginWithRecovery,
      loginWithPasskey,
      beginSSO,
      completeSSO,
      logout,
      refresh,
    }),
    [
      loading,
      session,
      signup,
      login,
      verifyTotp,
      loginWithRecovery,
      loginWithPasskey,
      beginSSO,
      completeSSO,
      logout,
      refresh,
    ],
  )

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

// The hook ships alongside its provider in this context module by design.
// eslint-disable-next-line react-refresh/only-export-components
export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext)
  if (!ctx) throw new Error('useAuth must be used within <AuthProvider>')
  return ctx
}
